  "wire_schema": "role_benchmark.player_action.v3",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H1",
        "statement": "period_s = 2*pi*sqrt(length_m/9.81), independent of bob_mass_kg and release_angle_deg",
        "confidence": 0.6
      },
      {
        "hypothesis_id": "H2",
        "statement": "period_s = 2*pi*sqrt(length_m/9.81)*(1 + 0.01*release_angle_deg)",
        "confidence": 0.25
      },
      {
        "hypothesis_id": "H3",
        "statement": "period_s = 2*pi*sqrt(length_m/9.81) + 0.1*bob_mass_kg",
        "confidence": 0.15
      }
    ]
  },
  "experiment": {
    "intent": "Measure period at a moderate length, small angle, and moderate mass to begin separating a standard length-only pendulum law from angle- or mass-dependent alternatives.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 0.5,
      "bob_mass_kg": 0.5,
      "release_angle_deg": 2.0
    },
    "readouts": [
      "period_s"
    ],
    "replicates": 10,
    "forecasts": {
      "period_s": {
        "H1": 1.4185,
        "H2": 1.4469,
        "H3": 1.4685
      }
    }
  },
  "final": null
}

